import React, { useState, useEffect } from "react";
import { Link, useLocation, useNavigate } from "react-router-dom";
import { getUser, logout } from "../utils/auth";

function Navbar() {
  const location = useLocation();
  const navigate = useNavigate();

  const [user, setUser] = useState(getUser());
  const [open, setOpen] = useState(false);
  const [search, setSearch] = useState("");

  // sync auth state
  useEffect(() => {
    const handleChange = () => setUser(getUser());
    window.addEventListener("authChanged", handleChange);

    return () => window.removeEventListener("authChanged", handleChange);
  }, []);

  const handleLogout = () => {
    logout();
    setUser(null);
    setOpen(false);
    window.dispatchEvent(new Event("authChanged"));
    navigate("/login");
  };

  const handleSearch = (e) => {
    e.preventDefault();
    if (!search.trim()) return;
    navigate(`/explore?search=${search}`);
  };

  return (
    <nav style={styles.nav}>

      {/* LOGO */}
      <div style={styles.logo} onClick={() => navigate("/")}>
        🏥 DocBook
      </div>

      {/* LINKS */}
      <div style={styles.links}>
        <Link to="/" style={styles.link}>Home</Link>
        <Link to="/explore" style={styles.link}>Explore Doctors</Link>
        <Link to="/add-doctor" style={styles.link}>Add Doctor</Link>
      </div>

      {/* SEARCH */}
      <form onSubmit={handleSearch} style={styles.searchBox}>
        <input
          type="text"
          placeholder="Search doctors..."
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          style={styles.searchInput}
        />
        <button style={styles.searchBtn}>🔍</button>
      </form>

      {/* AUTH SECTION */}
      <div style={{ position: "relative" }}>
        {user ? (
          <>
            <img
              src="https://randomuser.me/api/portraits/men/75.jpg"
              alt="user"
              style={styles.avatar}
              onClick={() => setOpen(!open)}
            />

            {open && (
              <div style={styles.dropdown}>
                <p style={styles.item}>👤 {user.name}</p>
                <Link to="/appointments" style={styles.item}>
                  📅 My Appointments
                </Link>
                <p onClick={handleLogout} style={styles.item}>
                  🚪 Logout
                </p>
              </div>
            )}
          </>
        ) : (
          <button
            style={styles.loginBtn}
            onClick={() => navigate("/login")}
          >
            Login
          </button>
        )}
      </div>
    </nav>
  );
}

const styles = {
  nav: {
    display: "flex",
    alignItems: "center",
    justifyContent: "space-between",
    padding: "12px 25px",
    background: "#fff",
    boxShadow: "0 2px 10px rgba(0,0,0,0.08)",
    position: "sticky",
    top: 0,
    zIndex: 1000,
  },

  logo: {
    fontSize: "20px",
    fontWeight: "bold",
    color: "#1976d2",
    cursor: "pointer",
  },

  links: {
    display: "flex",
    gap: "18px",
  },

  link: {
    textDecoration: "none",
    color: "#333",
    fontWeight: "500",
  },

  searchBox: {
    display: "flex",
    alignItems: "center",
    background: "#f5f5f5",
    borderRadius: "20px",
    padding: "5px 10px",
    width: "250px",
  },

  searchInput: {
    border: "none",
    outline: "none",
    background: "transparent",
    flex: 1,
  },

  searchBtn: {
    border: "none",
    background: "#1976d2",
    color: "#fff",
    borderRadius: "50%",
    width: "30px",
    height: "30px",
    cursor: "pointer",
  },

  avatar: {
    width: "38px",
    height: "38px",
    borderRadius: "50%",
    cursor: "pointer",
    border: "2px solid #1976d2",
  },

  dropdown: {
    position: "absolute",
    right: 0,
    top: "45px",
    background: "#fff",
    boxShadow: "0 4px 15px rgba(0,0,0,0.15)",
    borderRadius: "10px",
    width: "180px",
    padding: "10px",
  },

  item: {
    padding: "8px",
    cursor: "pointer",
    textDecoration: "none",
    color: "#333",
    display: "block",
  },

  loginBtn: {
    background: "#1976d2",
    color: "#fff",
    border: "none",
    padding: "8px 14px",
    borderRadius: "6px",
    cursor: "pointer",
  },
};

export default Navbar;
